type sqpWindow struct{Key string `json:"key"`;Address string `json:"address"`;Since time.Time `json:"since"`;End time.Time `json:"end"`;Input string `json:"input"`;InputSHA string `json:"input_sha256"`;Receipt string `json:"receipt"`;ReceiptSHA string `json:"receipt_sha256"`}
type sqpOccurrence struct{Seq int `json:"seq"`;SourceWallet string `json:"source_wallet"`;Event flowEvent `json:"event"`;LineSHA string `json:"literal_queue_line_sha256"`;Window sqpWindow `json:"native_source_window"`}
type sqpCandidate struct{Address string `json:"address"`;Occurrences []sqpOccurrence `json:"occurrences"`}
type sqpManifest struct{Source string `json:"source"`;Queue string `json:"queue_path"`;QueueSHA string `json:"queue_gzip_sha256"`;RawSHA string `json:"queue_lossless_jsonl_sha256"`;Trace string `json:"trace_path"`;TraceSHA string `json:"trace_sha256"`;Loader string `json:"loader_path"`;LoaderSHA string `json:"loader_sha256"`;States string `json:"states_path"`;StatesSHA string `json:"states_sha256"`;Restore string `json:"restore_manifest_path"`;RestoreSHA string `json:"restore_manifest_sha256"`;Candidates []sqpCandidate `json:"candidates"`}
func sqpDigest(path string)(string,error){f,e:=os.Open(path);if e!=nil{return "",e};defer f.Close();h:=sha256.New();if _,e=io.Copy(h,f);e!=nil{return "",e};return fmt.Sprintf("%x",h.Sum(nil)),nil}
func sqpValidate(m sqpManifest)error{verified:=map[string]string{};check:=func(path,want string)bool{h,ok:=verified[path];if !ok{var e error;h,e=sqpDigest(path);if e!=nil{return false};verified[path]=h};return h==want};if m.Source!=scpSource||len(m.Candidates)==0{return fmt.Errorf("prefetch source or empty manifest")};for _,v:=range [][2]string{{m.Queue,m.QueueSHA},{m.Trace,m.TraceSHA},{m.Loader,m.LoaderSHA},{m.States,m.StatesSHA},{m.Restore,m.RestoreSHA}}{if !check(v[0],v[1]){return fmt.Errorf("immutable prefetch binding hash")}}
 wanted:=map[int]sqpOccurrence{};seenAddress:=map[string]bool{};for _,c:=range m.Candidates{if c.Address==""||seenAddress[c.Address]||len(c.Occurrences)==0{return fmt.Errorf("candidate identity")};seenAddress[c.Address]=true;for _,o:=range c.Occurrences{if _,ok:=wanted[o.Seq];ok{return fmt.Errorf("duplicate candidate occurrence")};if o.Event.To!=c.Address||o.Event.From!=o.SourceWallet||o.Event.From==o.Event.To||o.Event.Dir!=apiOut||o.Event.Category!=apiTransfer||!o.Event.Amount.IsPositive(){return fmt.Errorf("queued production route guard")};if o.Window.Address!=o.SourceWallet||o.Event.Key.Time.Before(o.Window.Since)||!o.Event.Key.Time.Before(o.Window.End){return fmt.Errorf("native source window guard")};for _,v:=range [][2]string{{o.Window.Input,o.Window.InputSHA},{o.Window.Receipt,o.Window.ReceiptSHA}}{if !check(v[0],v[1]){return fmt.Errorf("native current input hash")}};var r struct{Source string `json:"source"`;InputSHA string `json:"current_input_sha256"`;Exact bool `json:"nonfee_input_exact"`};b,e:=os.ReadFile(o.Window.Receipt);if e!=nil||json.Unmarshal(b,&r)!=nil||r.Source!=scpSource||r.InputSHA!=o.Window.InputSHA||!r.Exact{return fmt.Errorf("native source receipt guard")};wanted[o.Seq]=o}}
 f,e:=os.Open(m.Queue);if e!=nil{return e};defer f.Close();z,e:=gzip.NewReader(f);if e!=nil{return e};defer z.Close();h:=sha256.New();scan:=bufio.NewScanner(io.TeeReader(z,h));scan.Buffer(make([]byte,65536),64*1024*1024);found:=map[int]bool{};for scan.Scan(){var row struct{Seq int `json:"seq"`;SourceWallet string `json:"source_wallet"`;Event flowEvent `json:"event"`};if e=json.Unmarshal(scan.Bytes(),&row);e!=nil{return e};o,ok:=wanted[row.Seq];if !ok{continue};if found[row.Seq]||row.SourceWallet!=o.SourceWallet||!reflect.DeepEqual(row.Event,o.Event)||scpHash(append(append([]byte(nil),scan.Bytes()...), '\n'))!=o.LineSHA{return fmt.Errorf("literal queued occurrence altered")};found[row.Seq]=true};if e=scan.Err();e!=nil{return e};if fmt.Sprintf("%x",h.Sum(nil))!=m.RawSHA||len(found)!=len(wanted){return fmt.Errorf("lossless queue or membership proof")};return nil
}
func TestOPS818QueueStopPrefetchPilot(t *testing.T){dir,path,want:=os.Getenv("OPS818_QUEUE_PREFETCH_PILOT_ROOT"),os.Getenv("OPS818_QUEUE_PREFETCH_MANIFEST"),os.Getenv("OPS818_QUEUE_PREFETCH_SHA256");if dir==""{t.Skip("private source pilot only")};if e:=os.MkdirAll(dir,0700);e!=nil{t.Fatal("private output failed")};h,e:=sqpDigest(path);if e!=nil||h!=want{t.Fatal("explicit candidate hash guard")};b,e:=os.ReadFile(path);var m sqpManifest;if e!=nil||json.Unmarshal(b,&m)!=nil||sqpValidate(m)!=nil{t.Fatal("independent immutable queue/native binding guard")};if scpVerifyProduction()!=nil{t.Fatal("source identity")}
 rec:=&scpRecorder{Phase:"source_connection"};cfg,e:=pgx.ParseConfig("host=127.0.0.1 port=15439 user=postgres dbname=cosmostax sslmode=disable application_name=ops818-private-queue-stop-pilot default_transaction_read_only=on");if e!=nil{t.Fatal("config")};cfg.Tracer=&scpTracer{rec};pool:=sql.OpenDB(&scpConnector{stdlib.GetConnector(*cfg),rec});defer pool.Close();pool.SetMaxOpenConns(1);db,e:=gorm.Open(postgres.New(postgres.Config{Conn:pool}),&gorm.Config{Logger:logger.Default.LogMode(logger.Silent)});if e!=nil{t.Fatal("source open")};defer func(){_ = schWrite(filepath.Join(dir,"terminal-actual-query-evidence.private.json"),map[string]any{"queries":rec.Queries,"wire":rec.Wire})}();s,e:=scsNewSession(db,rec,dir,1);if e!=nil{t.Fatal("one snapshot setup failed")};defer s.tx.Rollback();if schSync(dir)!=nil{t.Fatal("setup sync")}
 initial:=map[string]AddressLabel{};for k,v:=range s.l.labels{initial[k]=v};results:=map[string]flowStop{};start:=time.Now()
 for i,c:=range m.Candidates{before,e:=scpReadControls(s.tx);if e!=nil||before!=s.c{t.Fatal("same snapshot before")};q,w:=len(rec.Queries),len(rec.Wire);rec.Phase="queue_bound_actual_production_stop";stop,e:=s.l.stop(c.Address);queries,wire:=rec.Queries[q:],rec.Wire[w:];if e!=nil||scpVerifyStopRows(c.Address,s.l,stop,queries)!=nil||schArgs(queries,wire,c.Address)!=nil{t.Fatal("actual eager stop source evidence failed")};after,e:=scpReadControls(s.tx);if e!=nil||after!=s.c{t.Fatal("same snapshot after")};p:=map[string]any{"source":scpSource,"address":c.Address,"stop":stop,"controls":after,"queries":queries,"wire":wire,"queue_manifest_path":path,"queue_manifest_sha256":want,"queued_occurrences":c.Occurrences,"label_setup_path":s.setupPath,"label_setup_sha256":s.setupHash,"audit_requeries":0,"financially_accepted":false,"not_published":true};if schWrite(filepath.Join(dir,fmt.Sprintf("eager-%03d.proof.private.json",i+1)),p)!=nil{t.Fatal("raw proof write")};results[c.Address]=stop}
 eagerMillis:=float64(time.Since(start).Microseconds())/1000;lazy:=&dbFlowLoader{s:s.l.s,chain:s.l.chain,private:true,labels:initial,mu:s.l.mu,chans:map[string]string{}};compared:=0;for i:=len(m.Candidates)-1;i>=0&&compared<4;i--{c:=m.Candidates[i];got,e:=lazy.stop(c.Address);if e!=nil||got!=results[c.Address]{t.Fatal("actual eager versus reversed lazy production differs")};compared++};after,e:=scpReadControls(s.tx);if e!=nil||after!=s.c{t.Fatal("pilot final identity")};if schWrite(filepath.Join(dir,"pilot-result.private.json"),map[string]any{"source":scpSource,"controls":after,"candidates":len(results),"actual_reversed_lazy_comparisons":compared,"eager_elapsed_millis":eagerMillis,"queue_manifest_sha256":want,"same_label_setup_sha256":s.setupHash,"source_queries_are_metadata_only":true,"live_replies_modified":false,"financially_accepted":false})!=nil{t.Fatal("pilot result write")};fmt.Printf("phase=queue-bound-eager-pilot-passed count=%d\n",len(results))
}
